import{c as n,Z as s,Q as i,j as d,m as o,g as r,n as a,o as e,av as g}from"./chunks/framework.rWdQudnF.js";const k=JSON.parse('{"title":"质量属性与评估","description":"","frontmatter":{"title":"质量属性与评估"},"headers":[],"relativePath":"综合知识/架构设计/质量属性与评估.md","filePath":"综合知识/架构设计/质量属性与评估.md","lastUpdated":null}'),h={name:"综合知识/架构设计/质量属性与评估.md"};function p(u,t,b,c,q,m){const l=s("font");return i(),d("div",null,[t[7]||(t[7]=o(`<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 六大质量属性：性能/可用性/安全性/可修改性/可测试性/易用性</li><li>[x] 可靠性（MTTF/MTBF）与鲁棒性（Robustness）</li><li>[x] 可变性（Variability）概念</li><li>[x] 运行期 vs 开发期质量属性分类</li><li>[x] 质量属性场景六要素</li><li>[x] ATAM 架构权衡分析法</li><li>[x] SAAM 软件架构分析方法</li><li>[x] CBAM 成本效益分析法</li><li>[x] 非功能性需求四分类（操作性/性能/安全性/文化）</li><li>[x] 敏感点、权衡点与风险决策</li><li>[x] 效用树（Utility Tree）</li><li>[x] 质量属性与架构策略对应关系</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h2 id="质量属性" tabindex="-1">质量属性 <a class="header-anchor" href="#质量属性" aria-label="Permalink to &quot;质量属性&quot;">​</a></h2><h3 id="质量属性概述" tabindex="-1">质量属性概述 <a class="header-anchor" href="#质量属性概述" aria-label="Permalink to &quot;质量属性概述&quot;">​</a></h3><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517183007.png" alt="image.png"></p><blockquote><p>软件系统质量属性（Quality Attribute）是一个系统的可测量或可测试的属性，用来描述系统满足利益相关者需求的程度。</p></blockquote><p><strong>质量属性场景六要素：</strong></p><ol><li><strong>刺激源</strong>（Source）— 谁发出的刺激</li><li><strong>刺激</strong>（Stimulus）— 触发系统的事件</li><li><strong>环境</strong>（Environment）— 事件发生时的条件</li><li><strong>制品</strong>（Artifact）— 被影响的系统组成部分</li><li><strong>响应</strong>（Response）— 系统对刺激的反应行为</li><li><strong>响应度量</strong>（Response Measure）— 可量化的评估指标</li></ol><blockquote><p>简化三要素（场景最小描述）：<strong>刺激、环境、响应</strong></p></blockquote><hr><h3 id="运行期-vs-开发期质量属性-【软件系统的质量属性】" tabindex="-1">运行期 vs 开发期质量属性 【软件系统的质量属性】 <a class="header-anchor" href="#运行期-vs-开发期质量属性-【软件系统的质量属性】" aria-label="Permalink to &quot;运行期 vs 开发期质量属性 【软件系统的质量属性】&quot;">​</a></h3><p>可以将软件系统的质量属性分为<strong>开发期质量属性</strong>和<strong>运行期质量属性</strong> 2个部分。</p><h4 id="开发期质量属性" tabindex="-1">开发期质量属性 <a class="header-anchor" href="#开发期质量属性" aria-label="Permalink to &quot;开发期质量属性&quot;">​</a></h4><p>1.开发期质量属性主要指在软件开发阶段所关注的质量属性，主要包含6个方面。</p><ul><li>(1)易理解性：指设计被开发人员理解的难易程度。</li><li>(2)可扩展性：软件因适应新需求或需求变化而增加新功能的能力，也称为灵活性。</li><li>(3)可重用性：指重用软件系统或某一部分的难易程度。</li><li>(4)可测试性：对软件测试以证明其满足需求规范的难易程度。</li><li>(5)可维护性：当需要修改缺陷、增加功能、提高质量属性时，识别修改点并实施修改的难易程度。</li><li>(6)可移植性：将软件系统从一个运行环境转移到另一个不同的运行环境的难易程度。</li></ul><h4 id="运行期质量属性" tabindex="-1">运行期质量属性 <a class="header-anchor" href="#运行期质量属性" aria-label="Permalink to &quot;运行期质量属性&quot;">​</a></h4><p>2.运行期质量属性主要指在软件运行阶段所关注的质量属性，主要包含7个方面。</p><ul><li>(1)性能：性能是指软件系统及时提供相应服务的能力，如速度、吞吐量和容量等的要求。</li><li>(2)安全性：指软件系统同时兼顾向合法用户提供服务，以及阻止非授权使用的能力。</li><li>(3)可伸缩性：指当用户数和数据量增加时，软件系统维持高服务质量的能力。例如，通过增加服务器来提高能力。</li><li>(4)互操作性：指本软件系统与其他系统交换数据和相互调用服务的难易程度。</li><li>(5)可靠性：软件系统在一定的时间内持续无故障运行的能力。</li><li>(6)可用性：指系统在一定时间内正常工作的时间所占的比例。可用性会受到系统错误，恶意攻击，高负载等问题的影响。</li><li>(7)鲁棒性：是指软件系统在非正常情况（如用户进行了非法操作、相关的软硬件系统发生了故障等)下仍能够正常运行的能力，也称健壮性或容错性。</li></ul><blockquote><p>🎯 开发期质量属性：关注开发和维护过程的效率；运行期质量属性：关注系统在线运行时的表现。</p></blockquote><table tabindex="0"><thead><tr><th>分类</th><th>包含属性</th><th>特点</th></tr></thead><tbody><tr><td><strong>运行期质量属性</strong></td><td>性能、安全性、可用性、可靠性、鲁棒性、互操作性</td><td>用户在使用时可直接感知</td></tr><tr><td><strong>开发期质量属性</strong></td><td>可修改性、可测试性、可重用性、可维护性、可移植性</td><td>开发和维护阶段体现</td></tr></tbody></table><p>⚠️ 常见坑：可伸缩性（Scalability）是运行期质量属性（与用户数和数据量相关）。</p><hr><h3 id="面向架构评估的质量属性" tabindex="-1">面向架构评估的质量属性 <a class="header-anchor" href="#面向架构评估的质量属性" aria-label="Permalink to &quot;面向架构评估的质量属性&quot;">​</a></h3><h4 id="性能-performance" tabindex="-1">性能（Performance） <a class="header-anchor" href="#性能-performance" aria-label="Permalink to &quot;性能（Performance）&quot;">​</a></h4><ul><li>系统的响应能力：响应时间（多久响应）、吞吐量（单位时间处理事件个数）</li><li>典型场景：&quot;并发 10 万用户时，请求响应时间 &lt; 3 秒&quot;</li><li>架构策略：<strong>资源调度</strong>、<strong>引入并发</strong>、增加计算资源</li></ul><h4 id="可靠性-reliability" tabindex="-1">可靠性（Reliability） <a class="header-anchor" href="#可靠性-reliability" aria-label="Permalink to &quot;可靠性（Reliability）&quot;">​</a></h4><blockquote><p>🎯 可靠性 = 在规定条件和时间内完成规定功能的能力，核心指标是 MTBF（平均失效间隔时间）。</p></blockquote><ul><li>在意外或错误使用情况下维持功能特性的能力</li><li>**MTTF（平均失效等待时间）**和 <strong>MTBF（平均失效间隔时间）</strong>：在失效率为常数且修复时间很短的情况下，<strong>MTTF 和 MTBF 几乎相等</strong></li><li>与可用性的区别：可靠性侧重&quot;不出错&quot;，可用性侧重&quot;出错后能恢复&quot;</li></ul><p>可靠性：是软件系统<strong>在应用或系统错误面前</strong>，在意外或错误使用的情况下维持软件系统的功能特性的基本能力。如MTTF、MTBF。设计策略：心跳、Pig/Echo、冗余、选举。</p><p>包括容错和健壮性。</p><h4 id="可用性-availability" tabindex="-1"><strong>可用性（Availability）</strong> <a class="header-anchor" href="#可用性-availability" aria-label="Permalink to &quot;**可用性（Availability）**&quot;">​</a></h4><ul><li>系统故障后<strong>恢复并继续提供服务</strong>的能力</li><li>指标：MTBF（故障间隔时间）、MTTR（修复时间）</li><li>典型场景：&quot;主站宕机后，10 秒内自动切换至备用站点&quot;</li><li>架构策略：<strong>心跳</strong>（故障检测）、<strong>主动冗余</strong>（主备切换）</li></ul><h4 id="安全性-security" tabindex="-1"><strong>安全性（Security）</strong> <a class="header-anchor" href="#安全性-security" aria-label="Permalink to &quot;**安全性（Security）**&quot;">​</a></h4><ul><li>抵御恶意攻击的能力</li><li>典型场景：&quot;防止 99% 黑客攻击&quot;、&quot;对恶意操作进行报警和记录&quot;</li><li>架构策略：<strong>追踪审计</strong>、<strong>检测攻击</strong>、<strong>权限控制</strong></li></ul><h4 id="可修改性-modifiability" tabindex="-1"><strong>可修改性（Modifiability）</strong> <a class="header-anchor" href="#可修改性-modifiability" aria-label="Permalink to &quot;**可修改性（Modifiability）**&quot;">​</a></h4><ul><li>定位修改点并实施修改的难易程度</li><li>典型场景：&quot;二次开发时间不超过 3 个月&quot;、&quot;功能调整不超过 1 人月&quot;</li><li>包含：可维护性、可扩展性、结构重构、可移植性</li><li>架构策略：<strong>抽象接口</strong>、<strong>信息隐藏</strong>、<strong>接口-实现分离</strong></li></ul><h4 id="功能性" tabindex="-1">功能性 <a class="header-anchor" href="#功能性" aria-label="Permalink to &quot;功能性&quot;">​</a></h4><p>功能性：是系统所能完成所期望的工作的能力。一项任务的完成需要系统中许多或大多数构件的相互协作。</p><h4 id="可变性-variability" tabindex="-1">可变性（Variability） <a class="header-anchor" href="#可变性-variability" aria-label="Permalink to &quot;可变性（Variability）&quot;">​</a></h4><blockquote><p>🎯 可变性 = 体系结构经扩充或变更成为新体系结构的能力。注意：归属为可修改性的子维度，但<strong>独立考察</strong>。</p></blockquote><ul><li>可修改性包含：可维护性、可扩展性、结构重构、可移植性</li><li>⚠️ 常见坑：可变性<strong>不属于</strong>可修改性的组成部分（它是并列概念）</li></ul><h4 id="互操作性" tabindex="-1">互操作性 <a class="header-anchor" href="#互操作性" aria-label="Permalink to &quot;互操作性&quot;">​</a></h4><p>互操作性：作为系统组成部分的软件不是独立存在的，经常与其他系统或自身环境相互作用。</p><p>为了支持互操作性，软件体系结构必须<strong>为外部可视的功能特性和数据结构</strong>提供精心设计的软件入口。</p><p>程序和用其他编程语言编写的软件系统的交互作用就是互操作性的问题，也影响应用的软件体系结构。</p><hr><h3 id="质量属性-架构策略速查" tabindex="-1">质量属性-架构策略速查 <a class="header-anchor" href="#质量属性-架构策略速查" aria-label="Permalink to &quot;质量属性-架构策略速查&quot;">​</a></h3><p>有没有可测试性？</p><table tabindex="0"><thead><tr><th>质量属性</th><th>典型场景关键词</th><th>首选架构策略</th></tr></thead><tbody><tr><td><strong>性能</strong></td><td>响应时间、并发用户数、时延</td><td><strong>资源调度</strong>、引入并发</td></tr><tr><td><strong>可用性</strong></td><td>宕机切换、自动恢复、双机热备</td><td><strong>心跳</strong>、<strong>主动冗余</strong></td></tr><tr><td><strong>安全性</strong></td><td>防攻击、加密、入侵检测、报警记录</td><td><strong>追踪审计</strong>、检测攻击</td></tr><tr><td><strong>可修改性</strong></td><td>二次开发、功能调整、替换中间件</td><td><strong>抽象接口</strong>、接口-实现分离</td></tr><tr><td><strong>可测试性</strong></td><td>测试、验证</td><td>记录/回放、内置监控器</td></tr><tr><td><strong>易用性</strong></td><td>操作一致性、用户满意度、学习成本</td><td>—</td></tr></tbody></table><h3 id="面向架构评估的质量属性和运行期质量属性的区别" tabindex="-1">面向架构评估的质量属性和运行期质量属性的区别 <a class="header-anchor" href="#面向架构评估的质量属性和运行期质量属性的区别" aria-label="Permalink to &quot;面向架构评估的质量属性和运行期质量属性的区别&quot;">​</a></h3><p>两组质量属性分类，是从不同视角对软件质量属性的划分，二者是<strong>交叉重叠但不完全等同</strong>的关系</p><hr><p>两种分类的视角</p><table tabindex="0"><thead><tr><th>分类</th><th>划分依据</th><th>关注阶段</th><th>典型属性</th></tr></thead><tbody><tr><td><strong>开发期 vs. 运行期质量属性</strong></td><td>按<strong>时间阶段</strong>划分</td><td>开发阶段 vs. 运行阶段</td><td>开发期：可维护性、可扩展性、可测试性等<br>运行期：性能、可靠性、安全性等</td></tr><tr><td><strong>面向架构评估的质量属性</strong></td><td>按<strong>架构设计决策与评估</strong>的需要划分</td><td>跨越开发期和运行期，重点关注对架构有显著影响的属性</td><td>性能、可靠性、可用性、安全性、可修改性、功能性、可变性、互操作性</td></tr></tbody></table><hr><p>运行期质量属性 → 几乎全部出现在架构评估列表中</p><ul><li><strong>性能</strong> → 架构评估中的“性能”</li><li><strong>安全性</strong> → 架构评估中的“安全性”</li><li><strong>互操作性</strong> → 架构评估中的“互操作性”</li><li><strong>可靠性</strong> → 架构评估中的“可靠性”</li><li><strong>可用性</strong> → 架构评估中的“可用性”</li></ul><p>运行期特有的属性，在架构评估中被归入其他属性或细分</p><ul><li><strong>可伸缩性</strong>：通常被视为<strong>性能</strong>的一个子维度（通过资源调度、水平扩展来实现）。</li><li><strong>鲁棒性（健壮性/容错性）</strong>：通常被视为<strong>可靠性</strong>或<strong>可用性</strong>的一个方面（例如容错设计、异常处理）。</li></ul><p>架构评估列表中额外包含的、不属于运行期的属性</p><ul><li><strong>可修改性</strong>：属于<strong>开发期质量属性</strong>（包含可维护性、可扩展性、可移植性等）。</li><li><strong>功能性</strong>：跨越开发期和运行期，是系统“能否完成期望工作”的基本能力，架构评估中常单独列出。</li><li><strong>可变性</strong>：有时作为可修改性的子维度，有时独立考察（例如产品线架构中的变点设计），也属于开发期/设计期。</li></ul><hr><p>关系图</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│           面向架构评估的质量属性                  │</span></span>
<span class="line"><span>│  ┌───────────────────────────────────────────┐  │</span></span>
<span class="line"><span>│  │  运行期质量属性                            │  │</span></span>
<span class="line"><span>│  │  • 性能 (可伸缩性归入)                     │  │</span></span>
<span class="line"><span>│  │  • 安全性                                  │  │</span></span>
<span class="line"><span>│  │  • 互操作性                                │  │</span></span>
<span class="line"><span>│  │  • 可靠性 (鲁棒性归入)                     │  │</span></span>
<span class="line"><span>│  │  • 可用性                                  │  │</span></span>
<span class="line"><span>│  └───────────────────────────────────────────┘  │</span></span>
<span class="line"><span>│  ┌───────────────────────────────────────────┐  │</span></span>
<span class="line"><span>│  │  开发期/设计期质量属性                      │  │</span></span>
<span class="line"><span>│  │  • 可修改性 (含可维护性、可扩展性等)       │  │</span></span>
<span class="line"><span>│  │  • 可变性                                  │  │</span></span>
<span class="line"><span>│  │  • 功能性 (跨阶段)                         │  │</span></span>
<span class="line"><span>│  └───────────────────────────────────────────┘  │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────┘</span></span></code></pre></div>`,65)),r("ul",null,[t[5]||(t[5]=r("li",null,"考试中如果问“以下哪些属于运行期质量属性”，要能区分开发期属性（如可测试性、可移植性）不选。",-1)),r("li",null,[t[1]||(t[1]=a("如果问“",-1)),e(l,{color:"#f79646"},{default:g(()=>[...t[0]||(t[0]=[a("架构评估中通常考虑哪些质量属性",-1)])]),_:1}),t[2]||(t[2]=a("”，则要包含",-1)),t[3]||(t[3]=r("strong",null,"可修改性、可变性、功能性",-1)),t[4]||(t[4]=a("等看似不属于运行期的属性。",-1))]),t[6]||(t[6]=r("li",null,[a("注意"),r("strong",null,"可伸缩性"),a("和"),r("strong",null,"鲁棒性"),a("虽然不在标准运行期七项之外单独列出（有时独立），但通常可以归入性能/可靠性；考试中若选项同时出现，按教材定义选择。")],-1))]),t[8]||(t[8]=o('<hr><h3 id="补充-质量属性战术详解-architecture-tactics" tabindex="-1">补充：质量属性战术详解（Architecture Tactics） <a class="header-anchor" href="#补充-质量属性战术详解-architecture-tactics" aria-label="Permalink to &quot;补充：质量属性战术详解（Architecture Tactics）&quot;">​</a></h3><blockquote><p>战术（Tactics）是针对特定质量属性的具体设计决策，用来控制质量属性响应。选择题常考&quot;以下哪个是针对 X 属性的战术&quot;。</p></blockquote><p><strong>性能战术：</strong></p><table tabindex="0"><thead><tr><th>战术</th><th>说明</th></tr></thead><tbody><tr><td>引入并发</td><td>多线程/多进程并行处理</td></tr><tr><td>资源调度</td><td>优先级队列、动态资源分配</td></tr><tr><td>预计算/缓存</td><td>提前计算结果，减少实时计算</td></tr><tr><td>减少计算开销</td><td>算法优化、降低复杂度</td></tr></tbody></table><p><strong>可用性战术：</strong></p><table tabindex="0"><thead><tr><th>战术</th><th>说明</th></tr></thead><tbody><tr><td>心跳（Heartbeat）</td><td>故障检测，周期发送信号</td></tr><tr><td>主动冗余（Active Redundancy）</td><td>多节点同时运行，故障自动切换</td></tr><tr><td>被动冗余（Passive Redundancy）</td><td>主备切换，备用节点待命</td></tr><tr><td>异常检测与恢复</td><td>捕获异常并回滚到安全状态</td></tr></tbody></table><p><strong>安全性战术：</strong></p><table tabindex="0"><thead><tr><th>战术</th><th>说明</th></tr></thead><tbody><tr><td>认证（Authentication）</td><td>验证用户身份</td></tr><tr><td>授权（Authorization）</td><td>控制访问权限</td></tr><tr><td>加密（Encryption）</td><td>数据传输和存储加密</td></tr><tr><td>审计追踪（Audit Trail）</td><td>记录操作日志</td></tr></tbody></table><p><strong>可修改性战术：</strong></p><table tabindex="0"><thead><tr><th>战术</th><th>说明</th></tr></thead><tbody><tr><td>抽象接口</td><td>隐藏实现细节，面向接口编程</td></tr><tr><td>信息隐藏</td><td>封装变化点</td></tr><tr><td>运行时绑定</td><td>动态加载/插件机制</td></tr></tbody></table><blockquote><p>⚠️ 常见坑：&quot;设置进程监视器&quot;是可用性战术（监控进程健康状况），<strong>不是</strong>性能战术。</p></blockquote><hr><h2 id="系统架构评估" tabindex="-1">系统架构评估 <a class="header-anchor" href="#系统架构评估" aria-label="Permalink to &quot;系统架构评估&quot;">​</a></h2><p>系统架构评估是在<strong>对架构分析、评估的基础上</strong>，对架构策略的选取进行决策。</p><p>软件架构评估<strong>在架构设计之后，系统设计之前</strong>，因此与设计、实现、测试都没有关系。评估的目的是为了评估所采用的架构<strong>是否能解决软件系统需求</strong>，但不是单纯的确定是否满足需求。</p><h3 id="三种常用的评估方式" tabindex="-1">三种常用的评估方式 <a class="header-anchor" href="#三种常用的评估方式" aria-label="Permalink to &quot;三种常用的评估方式&quot;">​</a></h3><ul><li>基于**调查问卷（检查表）**的方式：类似于需求获取中的问卷调查方式，只不过是架构方面的问卷，要求评估人员对领域熟悉。</li><li>基于度量的方式：制定一些定量来度量架构，如代码行数等。要制定质量属性和度量结果之间的映射，要求评估人员对架构熟悉。涉及3个基本活动，首先需要建立质量属性和度量之间的映射原则，然后从软件架构文档中获取度量信息，最后根据映射原则分析推导出系统的质量属性。</li><li><strong>基于场景的方式</strong>：主要方法。首先要确定应用领域的功能和软件架构的结构之间的映射，然后要设计用于体现待评估质量属性的场景（即4+1视图中的场景），最后分析软件架构对场景的支持程度。要求评估人员即对领域熟悉，也对架构熟悉。</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517184302.png" alt="image.png"></p><h3 id="敏感点、权衡点与风险决策-★" tabindex="-1">敏感点、权衡点与风险决策 ★ <a class="header-anchor" href="#敏感点、权衡点与风险决策-★" aria-label="Permalink to &quot;敏感点、权衡点与风险决策 ★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>概念</th><th>定义</th><th>关键特征</th></tr></thead><tbody><tr><td><strong>敏感点</strong></td><td>一个或多个构件/关系的特性，其微小变化会对<strong>某个</strong>质量属性产生显著影响</td><td>影响单个质量属性</td></tr><tr><td><strong>权衡点</strong></td><td>影响<strong>多个</strong>质量属性的特性，是多个质量属性的敏感点</td><td>涉及多属性取舍</td></tr><tr><td><strong>风险点</strong></td><td>可能导致架构失败的决策</td><td>潜在负面结果</td></tr><tr><td><strong>非风险点</strong></td><td>对质量属性无显著影响的决策</td><td>可接受</td></tr></tbody></table><p>风险点与非风险点不是以标准专业术语形式出现的，只是一个常规概念，即可能引起风险的因素，可称为风险点。某个做法如果有隐患，有可能导致一些问题，则为风险点：而如果某件事是可行的可接受的，则为非风险点。</p><p>从三个方面对场景进行设计：刺激（事件）；环境（事件发生的环境）；响应（架构响应刺激的过程)</p><blockquote><p><strong>典型考题</strong>：改变加密级别 → 权衡点（影响安全性 ↑ + 性能 ↓）</p></blockquote><p><strong>识别规律：</strong></p><ul><li>只涉及一个质量属性 → 敏感点</li><li>涉及两个及以上质量属性的取舍 → 权衡点</li></ul><hr><h3 id="基于场景的架构分析方法-saam" tabindex="-1">基于场景的架构分析方法 SAAM <a class="header-anchor" href="#基于场景的架构分析方法-saam" aria-label="Permalink to &quot;基于场景的架构分析方法 SAAM&quot;">​</a></h3><p>软件架构分析方法</p><p>SAAM是一种非功能质量属性的架构分析方法，是最早形成文档并得到广泛应用的软件架构分析方法。</p><blockquote><p>SAAM 是最早形成文档并得到广泛应用的软件架构分析方法，最初主要用于评估<strong>可修改性</strong>。</p></blockquote><p><strong>五大评估步骤：</strong></p><ol><li><strong>场景开发</strong> — 体现系统所支持的各种活动</li><li><strong>架构描述</strong> — 定义系统组成</li><li><strong>单个场景评估</strong> — 逐一评估场景</li><li><strong>场景交互</strong> — 分析场景间的相互影响</li><li><strong>总体评估</strong> — 综合评价</li></ol><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517184615.png" alt="image.png"></p><p><strong>三大输入：</strong></p><ol><li>问题描述</li><li>需求声明</li><li><strong>体系结构描述</strong>（必需的分析对象）</li></ol><blockquote><p>⚠️ SAAM 评估过程<strong>不包括</strong>属性模型构造（那是 ATAM 的步骤）。</p></blockquote><h3 id="atam-架构权衡分析方法" tabindex="-1">ATAM（架构权衡分析方法） <a class="header-anchor" href="#atam-架构权衡分析方法" aria-label="Permalink to &quot;ATAM（架构权衡分析方法）&quot;">​</a></h3><p>让架构师明确如何权衡多个质量目标，参与者有评估小组、项目决策者和其他项目相关人。</p><p>ATAM被分为四个主要的活动领域，分别是场景和需求收集、体系结构视图和场景实现、属性模型构造和分析、折中。</p><p>整个评估过程强调<strong>以属性作为架构评估的核心概念</strong>。主要针<strong>对性能、可用性、安全性和可修改性</strong>，在系统开发之前，对这些质量属性进行评价和折中。</p><p>ATAM方法采用效用树(Utility tree)这一工具来对质量属性进行分类和优先级排序。效用树的结构包括：树根-质量属性-属性分类-质量属性场景（叶子节点）。</p><p>需要注意的是，ATAM主要关注4类质量属性：<strong>性能、安全性、可修改性和可用性</strong>，这是因为这4个质量属性是利益相关者最为关心的。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20260517200313.png" alt="image.png"></p><hr><blockquote><p>ATAM 主要在系统开发之前，针对<strong>性能、可用性、安全性和可修改性</strong>等质量属性进行评价和折中。</p></blockquote><p><strong>四大活动阶段：</strong></p><ol><li>场景和需求收集</li><li>架构视图和场景实现</li><li><strong>属性模型构造和分析</strong>（核心步骤）</li><li>折中（权衡分析）</li></ol><p><strong>效用树（Utility Tree）：</strong></p><ul><li>ATAM 的重要工具，树形结构从根到叶：<strong>树根 → 质量属性 → 属性分类 → 质量属性场景</strong></li><li>用于系统化分析架构质量属性，从抽象目标到具体场景分解</li></ul><p><strong>核心概念：</strong> 整个评估过程强调以<strong>属性</strong>作为架构评估的核心概念。场景从**风险承担者（Stakeholder）**的角度描述。</p><hr><h3 id="cbam-成本效益分析法" tabindex="-1">CBAM（成本效益分析法） <a class="header-anchor" href="#cbam-成本效益分析法" aria-label="Permalink to &quot;CBAM（成本效益分析法）&quot;">​</a></h3><blockquote><p>🎯 CBAM 在 ATAM 基础上构建，核心依据是**投资回报率（ROI）**选择架构策略。是对 ATAM 的补充，在质量属性确定后，再从成本效益角度进行分析。</p></blockquote><p><strong>主要步骤：</strong></p><ol><li>整理场景</li><li>分配效用（为场景分配效用值）</li><li>形成&quot;策略-场景-响应级别&quot;的对应关系</li><li>使用内插法确定期望质量属性响应级别的效用</li><li>计算各架构策略的总收益</li><li>根据受成本影响的 ROI 选择架构策略</li></ol><blockquote><p>🎯 CBAM 关注的核心焦点：在考虑经济成本和效益的前提下，对架构策略进行优先级排序。</p></blockquote><h3 id="非功能性需求四分类" tabindex="-1">非功能性需求四分类 <a class="header-anchor" href="#非功能性需求四分类" aria-label="Permalink to &quot;非功能性需求四分类&quot;">​</a></h3><blockquote><p>🎯 架构设计中的非功能性需求分为四类，用于指导架构策略选择。</p></blockquote><table tabindex="0"><thead><tr><th>分类</th><th>含义</th><th>典型示例</th></tr></thead><tbody><tr><td><strong>操作性需求</strong></td><td>与用户操作使用相关</td><td>界面个性化定制、支持主流标准协议</td></tr><tr><td><strong>性能需求</strong></td><td>响应时间、吞吐量、资源利用率</td><td>响应时间 ≤ 3s、支持 ≥ 2G 缓存</td></tr><tr><td><strong>安全性需求</strong></td><td>向合法用户服务、阻止非授权使用</td><td>密码加密传输、超时重登验证</td></tr><tr><td><strong>文化需求</strong></td><td>带有文化背景因素</td><td>支持多语言（汉语/英语/法语）</td></tr></tbody></table><p><strong>ATAM vs SAAM vs CBAM 对比总表：</strong></p><table tabindex="0"><thead><tr><th>方法</th><th>核心特点</th><th>关键输入</th><th>主要用途</th></tr></thead><tbody><tr><td>ATAM</td><td>质量属性建模与折中</td><td>质量需求、场景</td><td>多质量属性权衡</td></tr><tr><td>SAAM</td><td>场景驱动的架构评估</td><td>架构描述、问题声明</td><td>可修改性评估</td></tr><tr><td>CBAM</td><td>成本效益驱动的策略选择</td><td>ROI分析、效用分配</td><td>经济视角策略排序</td></tr></tbody></table>',62))])}const y=n(h,[["render",p]]);export{k as __pageData,y as default};
